PATCH_ID = 'ETH500_PSYCH_RISK_SCHEMA_20260922_V1'
VERSION = '1.0.1-eth-focus-risk-schema'

class Stop(RuntimeError): pass

def digest(data): return hashlib.sha256(data).hexdigest()

def canonical(obj): return json.dumps(obj, sort_keys=True, ensure_ascii=False, allow_nan=False).encode()

def atomic_bytes(p, data):
    p.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix='.'+p.name+'.', dir=p.parent)
    try:
        with os.fdopen(fd, 'wb') as f:
            f.write(data); f.flush(); os.fsync(f.fileno())
        os.chmod(tmp, 0o600)
        os.replace(tmp, p)
        d = os.open(str(p.parent), os.O_DIRECTORY)
        try: os.fsync(d)
        finally: os.close(d)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)

def safe_file(root, rel, optional=False):
    n=PurePosixPath(rel)
    if n.is_absolute() or '..' in n.parts: raise Stop('UNSAFE_RELATIVE_PATH')
    p=root/rel
    if any(x.is_symlink() for x in [p,*p.parents] if x!=root.parent and x.is_relative_to(root)):
        raise Stop('SYMLINK_NOT_SUPPORTED: '+rel)
    if not p.is_file():
        if optional and not p.exists(): return None
        raise Stop('REQUIRED_FILE_MISSING: '+rel)
    return p

def db_read(path):
    if not path.exists(): return {'state':{}, 'trades':0, 'signals':0}
    if path.is_symlink() or not path.is_file(): raise Stop('UNSAFE_DATABASE')
    with contextlib.closing(sqlite3.connect(path.resolve().as_uri()+'?mode=ro', uri=True, timeout=5)) as db:
        db.execute('PRAGMA query_only=ON');db.execute('BEGIN')
        if db.execute('PRAGMA quick_check').fetchone()!=('ok',): raise Stop('DATABASE_INTEGRITY_FAILED')
        tables={r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        if not {'state','trades','signals'}<=tables: raise Stop('NEW_DATABASE_SCHEMA_UNKNOWN')
        return {'state':{k:json.loads(v) for k,v in db.execute('SELECT key,json FROM state')},
                'trades':db.execute('SELECT COUNT(*) FROM trades').fetchone()[0],
                'signals':db.execute('SELECT COUNT(*) FROM signals').fetchone()[0]}

def require_unused(root, migration):
    if (root/'data/LIVE_ENABLED.json').exists():
        raise Stop('NEW_ENTRIES_ENABLED: run ./eth pause; no auto-authorization')
    for mode in ('live','paper'):
        value=db_read(root/'data'/f'{mode}.sqlite')
        s=value['state'];e=s.get('engine')
        if value['trades'] or value['signals'] or s.get('release_fingerprint'):
            raise Stop('EXISTING_RUN: this patch is only for a never-started ETH500 installation')
        if e is not None and migration.occupied(e):
            raise Stop('NEW_POSITION_OR_PENDING')
        if s.get('risk_migrated'):
            raise Stop('ALREADY_IMPORTED_RISK: do not overwrite; review the existing migration')
    migration.ensure_previous_safe(root)

def verify_set(root, old, changes):
    for rel, h in old.items():
        p=safe_file(root,rel)
        allowed={h}
        if rel in changes:allowed.add(digest(changes[rel]))
        if digest(p.read_bytes()) not in allowed:
            raise Stop('SOURCE_CHANGED: '+rel)
    for rel,b in changes.items():
        if rel not in old:
            p=safe_file(root,rel,optional=True)
            if p and digest(p.read_bytes())!=digest(b): raise Stop('CONFLICTING_PATCH_FILE: '+rel)
    known={str(root/n) for n in set(old)|set(changes)}
    if any(str(p) not in known for p in (root/'eth_core').glob('*.py')):
        raise Stop('EXTRA_CORE_CODE: unsupported local modifications')

def acquire(stack, path):
    path.parent.mkdir(parents=True,exist_ok=True)
    if path.is_symlink(): raise Stop('UNSAFE_LOCK')
    f=stack.enter_context(path.open('a+'))
    try: fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB)
    except BlockingIOError: raise Stop('MANAGER_LOCKED: '+str(path)) from None

def backup_db(src, dst):
    if not src.is_file():return
    with contextlib.closing(sqlite3.connect(src.resolve().as_uri()+'?mode=ro',uri=True,timeout=5)) as a:
        with contextlib.closing(sqlite3.connect(dst)) as b:
            a.backup(b)
    os.chmod(dst,0o600)

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--root',type=Path,default=Path.home()/'eth_larry_focus_500')
    p.add_argument('--check-only',action='store_true')
    args=p.parse_args()
    if sys.version_info<(3,11):raise Stop('PYTHON_3_11_REQUIRED')
    os.umask(0o077)
    root=args.root.expanduser().resolve()
    if not root.is_dir():raise Stop('ETH_ROOT_MISSING')
    old_manifest=json.loads(BUNDLE['original_manifest'])
    old=old_manifest['files']
    changes={k:base64.b64decode(v,validate=True) for k,v in BUNDLE['files'].items()}
    for rel,b in changes.items():
        if digest(b)!=BUNDLE['sha256'][rel]:raise Stop('PATCH_PAYLOAD_MISMATCH')
    target=json.loads(BUNDLE['target_manifest'])
    existing=safe_file(root,'SOURCE_MANIFEST.json').read_bytes()
    current=json.loads(existing)
    if current not in (old_manifest,target):raise Stop('MANIFEST_VERSION_UNKNOWN')
    verify_set(root,old,changes)
    all_installed=(current==target and all((root/r).is_file() and digest((root/r).read_bytes())==digest(b) for r,b in changes.items()))
    if all_installed:
        print('RISK_SCHEMA_ALREADY_INSTALLED: '+VERSION)
        print('No state, code, service, or authorization changed.');return 0
    for rel,b in changes.items():
        if rel.endswith('.py'):compile(b,str(rel),'exec')
    # Only import exact verified ETH code. Predecessor code is NEVER imported.
    sys.path.insert(0,str(root))
    from eth_core import migration
    with contextlib.ExitStack() as stack:
        acquire(stack,root/'data/risk-schema-install.lock')
        acquire(stack,root/'data/live.lock')
        acquire(stack,root/'data/paper.lock')
        require_unused(root,migration)
        specs=migration.sources(root)
        for spec in specs: acquire(stack,spec['db'].parent/'live.lock')
        require_unused(root,migration)
        stage=Path(stack.enter_context(tempfile.TemporaryDirectory(prefix='.eth500-risk-stage-',dir=root.parent)))
        for rel in old:
            dest=stage/rel;dest.parent.mkdir(parents=True,exist_ok=True)
            dest.write_bytes((root/rel).read_bytes())
        for rel,b in changes.items():
            dest=stage/rel;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(b)
        (stage/'SOURCE_MANIFEST.json').write_bytes(BUNDLE['target_manifest'].encode())
        loaded=importlib.util.spec_from_file_location('eth_core._risk_schema_precheck',stage/'eth_core/legacy_psych.py')
        mod=importlib.util.module_from_spec(loaded);loaded.loader.exec_module(mod)
        new_uid=db_read(root/'data/live.sqlite')['state'].get('account_uid')
        snapshots=[];proofs=[]
        for spec in specs:
            snap=migration.snapshot(spec);snapshots.append(snap)
            if not snap['uid'] or (new_uid and str(snap['uid'])!=str(new_uid)):
                raise Stop('PREDECESSOR_ACCOUNT_UNBOUND_OR_DIFFERENT')
            st=snap['state']
            if isinstance(st.get('portfolio_guard'),dict) and 'risk_capital_usdt' not in st:
                cap,base,proof=mod.psych_basis(spec,st)
                proofs.append({'root':str(spec['root']),**proof})
        if not proofs:raise Stop('EXPECTED_MISSING_PSYCH_BASIS_NOT_FOUND')
        print('== Source + saved-ledger basis verified ==',flush=True)
        print(json.dumps(proofs,ensure_ascii=False,indent=2),flush=True)
        if args.check_only:
            print('CHECK_ONLY_OK: no program or database changes');return 0
        print('== Isolated offline regression tests ==',flush=True)
        runner="import sys,unittest;sys.path.insert(0,sys.argv[1]);s=unittest.defaultTestLoader.discover(sys.argv[1]+'/tests');r=unittest.TextTestRunner(verbosity=2).run(s);raise SystemExit(0 if r.wasSuccessful() else 2)"
        env=dict(os.environ);env.pop('PYTHONPATH',None);env['PYTHONDONTWRITEBYTECODE']='1'
        r=subprocess.run([sys.executable,'-I','-B','-c',runner,str(stage)],cwd=stage,
                         env=env,capture_output=True,text=True,timeout=180)
        stamp=time.strftime('%Y%m%dT%H%M%SZ',time.gmtime())
        backup=Path(tempfile.mkdtemp(prefix='eth500-risk-schema-'+stamp+'-',dir=(root/'backups') if (root/'backups').is_dir() else root))
        os.chmod(backup,0o700)
        (backup/'tests.log').write_text(r.stdout+r.stderr,encoding='utf-8')
        for line in (r.stdout+r.stderr).splitlines()[-7:]:print(line)
        if r.returncode:raise Stop('TEST_FAILED: '+str(backup/'tests.log'))
        require_unused(root,migration)
        if migration.sources(root)!=specs:raise Stop('PREDECESSOR_SET_CHANGED')
        if [migration.snapshot(s)['digest'] for s in specs]!=[s['digest'] for s in snapshots]:
            raise Stop('PREDECESSOR_STATE_CHANGED_DURING_VALIDATION')
        for spec,snap in zip(specs,snapshots):
            if isinstance(snap['state'].get('portfolio_guard'),dict) and 'risk_capital_usdt' not in snap['state']:
                a=mod.psych_basis(spec,snap['state'])
                if not any(a[2]=={k:v for k,v in q.items() if k!='root'} for q in proofs):
                    raise Stop('PREDECESSOR_SOURCE_CHANGED')
        verify_set(root,old,changes)
        # Backups are genuine SQLite snapshots; no copying an active WAL file.
        backup_db(root/'data/live.sqlite',backup/'new-eth-before.sqlite')
        original={}
        for rel in [*changes,'SOURCE_MANIFEST.json']:
            f=root/rel
            original[rel]=f.read_bytes() if f.is_file() else None
            if f.is_file():
                saved=backup/'source-before'/rel;saved.parent.mkdir(parents=True,exist_ok=True)
                saved.write_bytes(original[rel])
        (backup/'basis_evidence.json').write_bytes(canonical(proofs))
        (backup/'installation.json').write_bytes(canonical({'patch':PATCH_ID,'version':VERSION,
            'new_live_authorized':False,'predecessors_modified':False,'databases_modified':False,
            'source_state_digests':[s['digest'] for s in snapshots]}))
        try:
            for rel,b in changes.items():atomic_bytes(root/rel,b)
            atomic_bytes(root/'SOURCE_MANIFEST.json',BUNDLE['target_manifest'].encode())
            for rel,h in target['files'].items():
                if digest((root/rel).read_bytes())!=h:raise Stop('POST_INSTALL_HASH_FAILED: '+rel)
        except BaseException:
            # Only restore source bytes; never replace or reset a database.
            for rel,b in original.items():
                if b is None:(root/rel).unlink(missing_ok=True)
                else:atomic_bytes(root/rel,b)
            raise
        print('RISK_SCHEMA_PATCHED: '+VERSION)
        print('Backup: '+str(backup))
        print('Source compatibility fixed. The actual risk import occurs during ./eth setup.')
        print('No account API, order, leverage, service start, live authorization, or DB update performed.')
        print('Next: cd ~/eth_larry_focus_500 && ./eth verify && ./eth setup')
        return 0

if __name__=='__main__':
    try:raise SystemExit(main())
    except KeyboardInterrupt:print('STOP: cancelled; no automatic LIVE start',file=sys.stderr);raise SystemExit(130)
    except Exception as exc:
        # Do not print arbitrary process/environment/credential payloads.
        if isinstance(exc,Stop) or type(exc).__name__ in ('SafetyError','DataError'):
            text=str(exc)
        else:text=type(exc).__name__
        print('STOP: '+text,file=sys.stderr);raise SystemExit(2)
